// разделы списка эффектов: логика по тому, что эффект делает
export const FX_GROUPS = {
	'Видео': ['depth', 'pixelsort', 'frames', 'slitscan'],
	'Анимация': ['trail'],
	'Движение': ['curl', 'gravity', 'twist'],
	'Звук и ритм': ['spectrum', 'wave', 'blast', 'shoots', 'chladni', 'scope'],
	'Разрушение': ['physics', 'explode', 'dissolve'],
	'Цифровые': ['voxel', 'glitch', 'datamosh'],
	'Графика': ['shadow', 'links', 'slice', 'feedback', 'echo', 'tracking'],
	'Управление': ['cursor', 'brush', 'camTrack'],
	'Эксперименты': ['hyper', 'vscreen'],
};

export const FX_GROUP_NAMES = Object.keys(FX_GROUPS);

{
	const rank = (l) => {
		for (const [gi, g] of FX_GROUP_NAMES.entries()) {
			const k = FX_GROUPS[g].indexOf(l.id);
			if (k >= 0) {
				l.group = g;
				return gi * 100 + k;
			}
		}
		return 999;
	};
	FX_LAYERS.sort((a, b) => rank(a) - rank(b));
}
